page Sim "/" {
  state paused = false
  state count = 0
  state frames = 0
  ref box
  ref ctx
  ref raf
  ref balls = []

  let W = 400
  let H = 300
  let R = 10

  fn makeBall() {
    let b = null
    for (let t = 0; t < 100; t++) {
      b = {
        x: R + Math.random() * (400 - 2 * R),
        y: R + Math.random() * (300 - 2 * R),
        vx: (Math.random() * 2 - 1) * 3,
        vy: (Math.random() * 2 - 1) * 3
      }
      let ok = true
      for o in balls {
        if Math.hypot(o.x - b.x, o.y - b.y) < 2 * R {
          ok = false
          break
        }
      }
      if ok {
        break
      }
    }
    return b
  }

  fn clamp(b) {
    if b.x < R {
      b.x = R
      b.vx = Math.abs(b.vx)
    }
    if b.x > 400 - R {
      b.x = 400 - R
      b.vx = -Math.abs(b.vx)
    }
    if b.y < R {
      b.y = R
      b.vy = Math.abs(b.vy)
    }
    if b.y > 300 - R {
      b.y = 300 - R
      b.vy = -Math.abs(b.vy)
    }
  }

  fn draw() {
    if !ctx {
      return
    }
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
    draw()
  }

  fn reset() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(makeBall())
    }
    count = balls.length
    frames = 0
    draw()
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      clamp(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d = Math.hypot(dx, dy)
        if d < 2 * R {
          let dvx = c.vx - a.vx
          let dvy = c.vy - a.vy
          if dvx * dx + dvy * dy < 0 {
            let tx = a.vx
            let ty = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tx
            c.vy = ty
          }
          let nx = d > 0 ? dx / d : 1
          let ny = d > 0 ? dy / d : 0
          let overlap = (2 * R - d) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          c.x += nx * overlap
          c.y += ny * overlap
          clamp(a)
          clamp(c)
        }
      }
    }
    draw()
    frames++
  }

  fn loop() {
    if !paused {
      step()
    }
    raf = requestAnimationFrame(loop)
  }

  mount {
    ctx = box.getContext("2d")
    reset()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas id="sim" ref=box width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> paused = !paused
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

