      vy: (Math.random() * 2 - 1) * 3,
      r: r,
      color: `hsl(${Math.floor(Math.random() * 360)}, 70%, 55%)`
    }
  }

  fn overlaps(b) {
    return balls.some(o => Math.hypot(o.x - b.x, o.y - b.y) < o.r + b.r)
  }

  fn newBall() {
    let b = randomBall()
    let tries = 0
    while overlaps(b) && tries < 100 {
      b = randomBall()
      tries++
    }
    return b
  }

  fn walls(b) {
    if b.x < b.r {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if b.x > 400 - b.r {
      b.x = 400 - b.r
      b.vx = -Math.abs(b.vx)
    }
    if b.y < b.r {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if b.y > 300 - b.r {
      b.y = 300 - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      walls(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d = Math.hypot(dx, dy)
        let minD = a.r + c.r
        if d < minD {
          if d == 0 {
            dx = 1
            dy = 0
            d = 1
          }
          let nx = dx / d
          let ny = dy / d
          let rel = (c.vx - a.vx) * nx + (c.vy - a.vy) * ny
          if rel < 0 {
            let tvx = a.vx
            let tvy = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tvx
            c.vy = tvy
          }
          let o = (minD - d) / 2
          a.x -= nx * o
          a.y -= ny * o
          c.x += nx * o
          c.y += ny * o
          walls(a)
          walls(c)
        }
      }
    }
  }

  fn draw() {
    ctx.clearRect(0, 0, 400, 300)
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fillStyle = b.color
      ctx.fill()
    }
  }

  fn tick() {
    if !paused {
      step()
      draw()
      frames++
    }
    raf = requestAnimationFrame(tick)
  }

  fn reset() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(newBall())
    }
    count = balls.length
    frames = 0
    draw()
  }

  fn add() {
    balls.push(newBall())
    count = balls.length
    if paused {
      draw()
    }
  }

  mount {
    ctx = box.getContext("2d")
    balls = []
    reset()
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  style {
    .board { border: 1px solid var(--a-border); background: var(--a-surface); }
  }

