import { useCallback, useEffect, useRef, useState } from "react";

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

type Ball = { x: number; y: number; vx: number; vy: number; color: string };

const COLORS = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#a855f7", "#ec4899", "#14b8a6", "#f97316"];

function randomBall(existing: Ball[]): Ball {
  let x = 0;
  let y = 0;
  for (let attempt = 0; attempt < 200; attempt++) {
    x = R + Math.random() * (W - 2 * R);
    y = R + Math.random() * (H - 2 * R);
    const overlaps = existing.some((b) => Math.hypot(b.x - x, b.y - y) < 2 * R);
    if (!overlaps) break;
  }
  return {
    x,
    y,
    vx: (Math.random() * 2 - 1) * 3,
    vy: (Math.random() * 2 - 1) * 3,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

function makeBalls(n: number): Ball[] {
  const arr: Ball[] = [];
  for (let i = 0; i < n; i++) arr.push(randomBall(arr));
  return arr;
}

function clampToWalls(b: Ball) {
  if (b.x < R) {
    b.x = R;
    b.vx = Math.abs(b.vx);
  } else if (b.x > W - R) {
    b.x = W - R;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y < R) {
    b.y = R;
    b.vy = Math.abs(b.vy);
  } else if (b.y > H - R) {
    b.y = H - R;
    b.vy = -Math.abs(b.vy);
  }
}

function step(balls: Ball[]) {
  for (const b of balls) {
    b.vy += G;
    b.x += b.vx;
    b.y += b.vy;
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const c = balls[j];
      let dx = c.x - a.x;
      let dy = c.y - a.y;
      let dist = Math.hypot(dx, dy);
      if (dist < 2 * R) {
        if (dist === 0) {
          dx = 1;
          dy = 0;
          dist = 1;
        }
        const nx = dx / dist;
        const ny = dy / dist;
        const approaching = (c.vx - a.vx) * nx + (c.vy - a.vy) * ny < 0;
        if (approaching) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = c.vx;
          a.vy = c.vy;
          c.vx = tvx;
          c.vy = tvy;
        }
        const overlap = (2 * R - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        c.x += nx * overlap;
        c.y += ny * overlap;
      }
    }
  }
  for (const b of balls) clampToWalls(b);
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [initial] = useState(() => makeBalls(5));
  const ballsRef = useRef<Ball[]>(initial);
  const framesRef = useRef(0);
  const [count, setCount] = useState(5);
  const [frames, setFrames] = useState(0);
  const [paused, setPaused] = useState(false);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#f8fafc";
    ctx.fillRect(0, 0, W, H);
    for (const b of ballsRef.current) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.strokeStyle = "#1e293b";
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  }, []);

  useEffect(() => {
    if (paused) {
      draw();
      return;
    }
    let id = 0;
    const loop = () => {
      step(ballsRef.current);
      draw();
      framesRef.current += 1;
      setFrames(framesRef.current);
      id = requestAnimationFrame(loop);
    };
    id = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(id);
  }, [paused, draw]);

  const handleAdd = () => {
    ballsRef.current.push(randomBall(ballsRef.current));
    setCount(ballsRef.current.length);
    if (paused) draw();
  };

  const handleReset = () => {
    ballsRef.current = makeBalls(5);
    framesRef.current = 0;
    setFrames(0);
    setCount(5);
    if (paused) draw();
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center gap-4 bg-slate-100 p-6">
      <h1 className="text-2xl font-bold text-slate-800">Simulación de pelotas</h1>
      <canvas
        id="sim"
        ref={canvasRef}
        width={W}
        height={H}
        className="border-2 border-slate-700 rounded bg-slate-50"
      />
      <div className="flex gap-2">
        <button
          onClick={handleAdd}
          className="px-4 py-2 rounded bg-green-600 text-white font-medium hover:bg-green-700"
        >
          Agregar
        </button>
        <button
          onClick={() => setPaused((p) => !p)}
          className="px-4 py-2 rounded bg-blue-600 text-white font-medium hover:bg-blue-700"
        >
          {paused ? "Reanudar" : "Pausar"}
        </button>
        <button
          onClick={handleReset}
          className="px-4 py-2 rounded bg-red-600 text-white font-medium hover:bg-red-700"
        >
          Reiniciar
        </button>
      </div>
      <div className="flex gap-6 text-slate-700 font-mono">
        <span>Pelotas: {count}</span>
        <span>Cuadros: {frames}</span>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

type Ball = { x: number; y: number; vx: number; vy: number; color: string };

const COLORS = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#a855f7", "#f97316", "#14b8a6", "#ec4899"];

function makeBall(existing: Ball[]): Ball {
  let x = 0;
  let y = 0;
  for (let attempt = 0; attempt < 50; attempt++) {
    x = R + Math.random() * (W - 2 * R);
    y = R + Math.random() * (H - 2 * R);
    const ok = existing.every((b) => Math.hypot(b.x - x, b.y - y) >= 2 * R);
    if (ok) break;
  }
  const speed = 1 + Math.random() * 3;
  const ang = Math.random() * Math.PI * 2;
  return {
    x,
    y,
    vx: Math.cos(ang) * speed,
    vy: Math.sin(ang) * speed,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

function makeBalls(n: number): Ball[] {
  const arr: Ball[] = [];
  for (let i = 0; i < n; i++) arr.push(makeBall(arr));
  return arr;
}

function clampInside(b: Ball) {
  if (b.x - R < 0) {
    b.x = R;
    b.vx = Math.abs(b.vx);
  } else if (b.x + R > W) {
    b.x = W - R;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y - R < 0) {
    b.y = R;
    b.vy = Math.abs(b.vy);
  } else if (b.y + R > H) {
    b.y = H - R;
    b.vy = -Math.abs(b.vy);
  }
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[]>(makeBalls(5));
  const framesRef = useRef(0);
  const [paused, setPaused] = useState(false);
  const [count, setCount] = useState(5);
  const [frames, setFrames] = useState(0);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#f8fafc";
    ctx.fillRect(0, 0, W, H);
    for (const b of ballsRef.current) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.strokeStyle = "#1e293b";
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  }, []);

  const step = useCallback(() => {
    const balls = ballsRef.current;
    for (const b of balls) {
      b.vy += G;
      b.x += b.vx;
      b.y += b.vy;
      clampInside(b);
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let dist = Math.hypot(dx, dy);
        if (dist < 2 * R) {
          if (dist === 0) {
            dx = 0.01;
            dy = 0;
            dist = 0.01;
          }
          const nx = dx / dist;
          const ny = dy / dist;
          const rel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
          if (rel < 0) {
            const tvx = a.vx;
            const tvy = a.vy;
            a.vx = b.vx;
            a.vy = b.vy;
            b.vx = tvx;
            b.vy = tvy;
          }
          const overlap = (2 * R - dist) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          b.x += nx * overlap;
          b.y += ny * overlap;
          clampInside(a);
          clampInside(b);
        }
      }
    }
  }, []);

  useEffect(() => {
    draw();
    if (paused) return;
    let id = 0;
    const loop = () => {
