function makeBall(): Ball {
  return {
    x: rand(R, W - R),
    y: rand(R, H - R),
    vx: rand(-3, 3),
    vy: rand(-3, 3),
    color: `hsl(${Math.floor(Math.random() * 360)}, 70%, 50%)`,
  };
}

function makeBalls(n: number): Ball[] {
  return Array.from({ length: n }, makeBall);
}

function clampToBounds(b: Ball) {
  if (b.x < R) b.x = R;
  if (b.x > W - R) b.x = W - R;
  if (b.y < R) b.y = R;
  if (b.y > H - R) b.y = H - R;
}

export default function App() {
  let canvas: HTMLCanvasElement | undefined;
  let balls: Ball[] = makeBalls(INITIAL);
  let rafId: number | null = null;

  const [count, setCount] = createSignal(balls.length);
  const [frames, setFrames] = createSignal(0);
  const [paused, setPaused] = createSignal(false);

  function update() {
    for (const b of balls) {
      b.vy += G;
      b.x += b.vx;
      b.y += b.vy;

      if (b.x < R) {
        b.x = R;
        b.vx = Math.abs(b.vx);
      } else if (b.x > W - R) {
        b.x = W - R;
        b.vx = -Math.abs(b.vx);
      }
      if (b.y < R) {
        b.y = R;
        b.vy = Math.abs(b.vy);
      } else if (b.y > H - R) {
        b.y = H - R;
        b.vy = -Math.abs(b.vy);
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const dist = Math.hypot(dx, dy);
        if (dist < 2 * R) {
          const approaching = (a.vx - b.vx) * dx + (a.vy - b.vy) * dy > 0;
          if (approaching) {
            const tvx = a.vx;
            const tvy = a.vy;
            a.vx = b.vx;
            a.vy = b.vy;
            b.vx = tvx;
            b.vy = tvy;
          }
          // separar para que no queden superpuestas
          const nx = dist === 0 ? 1 : dx / dist;
          const ny = dist === 0 ? 0 : dy / dist;
          const overlap = (2 * R - dist) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          b.x += nx * overlap;
          b.y += ny * overlap;
          clampToBounds(a);
          clampToBounds(b);
        }
      }
    }
  }

  function draw() {
    const ctx = canvas?.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
    }
  }

  function loop() {
    update();
    draw();
    setFrames((f) => f + 1);
    rafId = requestAnimationFrame(loop);
  }

  function start() {
    if (rafId === null) rafId = requestAnimationFrame(loop);
  }

  function stop() {
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  }

  function togglePause() {
    if (paused()) {
      setPaused(false);
      start();
    } else {
      setPaused(true);
      stop();
    }
  }

  function add() {
    balls.push(makeBall());
    setCount(balls.length);
    if (paused()) draw();
  }

  function reset() {
    balls = makeBalls(INITIAL);
    setCount(balls.length);
    setFrames(0);
    if (paused()) draw();
  }

  onMount(() => {
    draw();
    start();
  });

  onCleanup(stop);

  return (
    <div class="p-4 flex flex-col items-start gap-3">
      <canvas
        id="sim"
        ref={canvas}
        width={W}
        height={H}
        class="border border-gray-400 bg-white"
      />
      <div class="flex gap-2">
        <button
          class="px-3 py-1 rounded bg-blue-600 text-white hover:bg-blue-700"
          onClick={add}
        >
          Agregar
        </button>
        <button
          class="px-3 py-1 rounded bg-yellow-500 text-white hover:bg-yellow-600"
          onClick={togglePause}
        >
          {paused() ? "Reanudar" : "Pausar"}
        </button>
        <button
          class="px-3 py-1 rounded bg-red-600 text-white hover:bg-red-700"
          onClick={reset}
        >
          Reiniciar
        </button>
      </div>
      <div class="flex gap-4 font-mono">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frames()}</span>
      </div>
    </div>
  );
}

import { createSignal, onMount, onCleanup } from "solid-js";

type Ball = { x: number; y: number; vx: number; vy: number; color: string };

const W = 400;
const H = 300;
const R = 10;
const GRAVITY = 0.2;
const COLORS = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#a855f7", "#ec4899", "#14b8a6", "#f97316"];

function rand(min: number, max: number) {
  return min + Math.random() * (max - min);
}

function makeBall(existing: Ball[]): Ball {
  let x = rand(R, W - R);
  let y = rand(R, H - R);
  for (let attempt = 0; attempt < 50; attempt++) {
    const ok = existing.every((b) => Math.hypot(b.x - x, b.y - y) >= 2 * R);
    if (ok) break;
    x = rand(R, W - R);
    y = rand(R, H - R);
  }
  return {
    x,
    y,
    vx: rand(-3, 3),
    vy: rand(-3, 3),
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

function makeBalls(n: number): Ball[] {
  const arr: Ball[] = [];
  for (let i = 0; i < n; i++) arr.push(makeBall(arr));
  return arr;
}

function clampBall(b: Ball) {
  if (b.x - R < 0) {
    b.x = R;
    b.vx = Math.abs(b.vx);
  } else if (b.x + R > W) {
    b.x = W - R;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y - R < 0) {
    b.y = R;
    b.vy = Math.abs(b.vy);
  } else if (b.y + R > H) {
    b.y = H - R;
    b.vy = -Math.abs(b.vy);
  }
}

export default function App() {
  let canvas: HTMLCanvasElement | undefined;
  let balls: Ball[] = makeBalls(5);
  let rafId: number | null = null;

  const [count, setCount] = createSignal(balls.length);
  const [frames, setFrames] = createSignal(0);
  const [paused, setPaused] = createSignal(false);

  const step = () => {
    for (const b of balls) {
      b.vy += GRAVITY;
      b.x += b.vx;
      b.y += b.vy;
      clampBall(b);
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const c = balls[j];
        const dx = c.x - a.x;
        const dy = c.y - a.y;
        let dist = Math.hypot(dx, dy);
        if (dist < 2 * R) {
          let nx = 1;
          let ny = 0;
          if (dist > 0) {
            nx = dx / dist;
            ny = dy / dist;
          } else {
            dist = 0;
          }
          const approaching = (c.vx - a.vx) * nx + (c.vy - a.vy) * ny < 0;
          if (approaching) {
            const tvx = a.vx;
            const tvy = a.vy;
            a.vx = c.vx;
            a.vy = c.vy;
            c.vx = tvx;
            c.vy = tvy;
          }
          const overlap = (2 * R - dist) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          c.x += nx * overlap;
          c.y += ny * overlap;
          clampBall(a);
          clampBall(c);
        }
      }
    }
  };

  const draw = () => {
    const ctx = canvas?.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
    }
  };

  const loop = () => {
    step();
    draw();
    setFrames((f) => f + 1);
    rafId = requestAnimationFrame(loop);
  };

  const start = () => {
    if (rafId === null) rafId = requestAnimationFrame(loop);
  };

  const stop = () => {
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  };

  onMount(() => {
    draw();
    start();
  });

  onCleanup(stop);

  const add = () => {
    balls.push(makeBall(balls));
    setCount(balls.length);
    if (paused()) draw();
  };

  const togglePause = () => {
    if (paused()) {
      setPaused(false);
      start();
    } else {
      setPaused(true);
      stop();
    }
  };

  const reset = () => {
    balls = makeBalls(5);
    setCount(balls.length);
    setFrames(0);
    if (paused()) draw();
  };

  return (
    <div class="min-h-screen flex flex-col items-center justify-center gap-4 bg-gray-100 p-4">
      <canvas
        id="sim"
        ref={canvas}
        width={W}
        height={H}
        class="bg-white border border-gray-400 rounded shadow"
      />
      <div class="flex gap-2">
        <button
          class="px-4 py-2 rounded bg-blue-500 text-white hover:bg-blue-600"
          onClick={add}
        >
          Agregar
        </button>
        <button
          class="px-4 py-2 rounded bg-yellow-500 text-white hover:bg-yellow-600"
          onClick={togglePause}
        >
          {paused() ? "Reanudar" : "Pausar"}
        </button>
        <button
          class="px-4 py-2 rounded bg-red-500 text-white hover:bg-red-600"
          onClick={reset}
        >
          Reiniciar
        </button>
      </div>
      <div class="flex gap-6 text-gray-800 font-mono">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frames()}</span>
      </div>
    </div>
  );
}
